import React from 'react';
import { Card } from 'react-bootstrap';

function StaffDashboard({ user }) {
  return (
    <div className="dashboard-content">
      <div className="welcome-banner">
        <h2>Good Morning, {user.stfnm || 'Staff'}!</h2>
        <p>Here's your schedule for today.</p>
      </div>

      <div className="feed-section">
        <h6 className="feed-title">Today's Timetable</h6>
        <Card className="feed-card mb-4">
          <Card.Body className="text-center text-muted">
            <div className="py-3">No classes assigned for today</div>
          </Card.Body>
        </Card>

        <div className="dashboard-study-illustration" aria-hidden="true">
          <img src="/images/home-study.png" alt="" />
        </div>
      </div>
    </div>
  );
}

export default StaffDashboard;
